package vn.svframe.svframelib.api.crafting.recipes; import vn.svframe.svframelib.api.crafting.ingredients.*; import vn.svframe.svframelib.api.crafting.outputs.MythicRecipeOutput; import vn.svframe.svframelib.api.util.Ref; import net.minecraft.util.Identifier; import java.util.*; import java.util.function.Predicate; public class MythicRecipeBlueprint { private final MythicRecipe main; private final MythicRecipeOutput result; private final Identifier id; private final Map<String,MythicRecipe> side=new LinkedHashMap<>(); private final ArrayList<MythicRecipeStation> deployed=new ArrayList<>(); private final ArrayList<String> permissions=new ArrayList<>(); public MythicRecipeBlueprint(MythicRecipe m,MythicRecipeOutput r){this(m,r,null);} public MythicRecipeBlueprint(MythicRecipe m,MythicRecipeOutput r,Identifier id){main=m;result=r;this.id=id;} public Identifier getNk(){return id;} public boolean canDisplayInRecipeBook(){return id!=null&&main instanceof VanillaBookableRecipe&&result instanceof VanillaBookableOutput;} public MythicRecipeOutput getResult(){return result;} public MythicRecipe getMainCheck(){return main;} public ArrayList<String> getSideInventoryNames(){return new ArrayList<>(side.keySet());} public MythicRecipe getSideCheck(String n){return side.get(n);} public boolean hasSideInventory(String n){return side.containsKey(n);} public void addSideCheck(String n,MythicRecipe r){side.put(n,r);} public MythicBlueprintInventory matches(MythicBlueprintInventory inv,Ref<Integer> amount){MythicRecipeInventory m=main.matches(inv.getMainInventory(),amount);if(m==null)return null;MythicBlueprintInventory out=new MythicBlueprintInventory(m,inv.getResultInventory().clone());for(String n:side.keySet()){MythicRecipeInventory source=inv.getSideInventory(n);if(source==null)return null;MythicRecipeInventory checked=side.get(n).matches(source,amount);if(checked==null)return null;out.addSideInventory(n,checked);}return out;} public void deploy(MythicRecipeStation s){if(!deployed.contains(s))deployed.add(s);MythicCraftingManager.deployBlueprint(this,s);} public ArrayList<MythicRecipeStation> getDeployedFor(){return new ArrayList<>(deployed);} public void disable(){deployed.clear();MythicCraftingManager.removeBlueprint(this);} public ArrayList<String> getRequiredPermissions(){return new ArrayList<>(permissions);} public void addRequiredPermission(String p){if(p!=null&&!p.isBlank()&&!permissions.contains(p))permissions.add(p);} public void clearRequiredPermissions(){permissions.clear();} public boolean checkPermissions(Predicate<String> check){for(String p:permissions)if(!check.test(p))return false;return true;} }
